/* ---------- M01: el viaje de una request ---------- */
SD.defineGlossary([
  { id: 'rtt', term: 'RTT', en: 'Round-Trip Time', cat: 'redes', mods: ['m01'],
    deep: 'm01#rtt',
    short: 'Tiempo de ida y vuelta de un paquete entre dos puntos. Casi todos los protocolos cuestan "N RTT", así que la distancia física multiplica su costo.' },
  { id: 'dns', term: 'DNS', en: 'Domain Name System', cat: 'redes', mods: ['m01'],
    deep: 'm01#dns', basic: true,
    short: 'La base de datos distribuida y jerárquica que traduce nombres (www.ejemplo.com) a direcciones IP. Cada nivel delega en el siguiente: raíz, TLD y servidor autoritativo.' },
  { id: 'ttl', term: 'TTL', en: 'Time To Live', cat: 'redes', mods: ['m01', 'm04'],
    deep: 'm01#dns-ttl', basic: true,
    short: 'Cuánto tiempo puede guardarse una respuesta en caché antes de volver a pedirla. Un TTL bajo permite cambiar rápido; uno alto reduce consultas y resiste mejor las caídas.' },
  { id: 'resolver', term: 'Resolver recursivo', en: 'Recursive resolver', cat: 'redes', mods: ['m01'],
    deep: 'm01#dns-actores', aliases: ['resolvers recursivos', 'recursive resolver'],
    short: 'Servidor DNS (del ISP, 1.1.1.1, 8.8.8.8) que recorre la jerarquía por el cliente y cachea las respuestas para todos sus usuarios.' },
  { id: 'tcp-handshake', term: 'Handshake de TCP', en: 'Three-way handshake', cat: 'redes', mods: ['m01'],
    deep: 'm01#tcp-handshake', aliases: ['handshake TCP', 'three-way handshake', 'handshake de tres vías'],
    short: 'SYN, SYN-ACK y ACK: los tres mensajes con los que cliente y servidor abren una conexión TCP. Cuesta una ida y vuelta completa antes de enviar datos.' },
  { id: 'slow-start', term: 'Slow start', en: 'TCP slow start', cat: 'redes', mods: ['m01'],
    deep: 'm01#slow-start', noauto: true,
    short: 'TCP empieza enviando poco (10 segmentos, ~14 kB) y duplica la ventana en cada ida y vuelta mientras no haya pérdidas. Por eso una conexión nueva es lenta para respuestas grandes.' },
  { id: 'hol-blocking', term: 'Head-of-line blocking', en: 'Head-of-line blocking', cat: 'redes', mods: ['m01'],
    deep: 'm01#hol', aliases: ['HOL blocking', 'bloqueo de cabeza de línea'],
    short: 'Cuando lo que va primero en una fila frena todo lo que viene detrás. En HTTP/2 sobre TCP, un paquete perdido detiene a todos los streams hasta su retransmisión.' },
  { id: 'tls', term: 'TLS', en: 'Transport Layer Security', cat: 'seguridad', mods: ['m01', 'm10'],
    deep: 'm01#tls', basic: true,
    short: 'El protocolo que cifra y autentica una conexión (la S de HTTPS). TLS 1.3 completa su handshake en una sola ida y vuelta.' },
  { id: 'sni', term: 'SNI', en: 'Server Name Indication', cat: 'seguridad', mods: ['m01'],
    deep: 'm01#sni',
    short: 'Campo del ClientHello de TLS con el nombre del sitio al que se quiere conectar. Permite que una misma IP sirva miles de dominios con certificados distintos.' },
  { id: 'quic', term: 'QUIC', en: 'QUIC', cat: 'redes', mods: ['m01'],
    deep: 'm01#quic',
    short: 'Protocolo de transporte sobre UDP que integra TLS 1.3 y multiplexa streams independientes. Es la base de HTTP/3: menos idas y vueltas y sin head-of-line blocking entre streams.' },
  { id: 'zero-rtt', term: '0-RTT', en: 'Zero round-trip resumption', cat: 'seguridad', mods: ['m01'],
    deep: 'm01#zero-rtt',
    short: 'Reanudación de TLS 1.3 o QUIC en la que el cliente envía datos en el primer paquete. Esos datos pueden ser reenviados por un atacante, así que solo sirven para requests idempotentes.' },
  { id: 'keep-alive', term: 'Keep-alive', en: 'Persistent connection', cat: 'redes', mods: ['m01'],
    deep: 'm01#tcp-reusar', basic: true,
    short: 'Mantener abierta una conexión para reutilizarla en requests siguientes y no pagar otra vez los handshakes de TCP y TLS.' },
  { id: 'hsts', term: 'HSTS', en: 'HTTP Strict Transport Security', cat: 'seguridad', mods: ['m01'],
    deep: 'm01#hsts',
    short: 'Header con el que un sitio le dice al navegador "conéctate a mí solo por HTTPS" durante un tiempo. Evita la primera request insegura por HTTP.' },
  { id: 'cdn', term: 'CDN', en: 'Content Delivery Network', cat: 'edge', mods: ['m01', 'm28'],
    deep: 'm28#cache',
    basic: true,
    short: 'Red de servidores repartidos por el mundo que terminan conexiones cerca del usuario, cachean contenido y reenvían al origen por conexiones ya abiertas.' },
  { id: 'pop', term: 'PoP', en: 'Point of Presence', cat: 'edge', mods: ['m01', 'm28'],
    deep: 'm28#anycast',
    short: 'Cada ubicación física de una CDN o de una red (un datacenter en una ciudad). El usuario llega al PoP más cercano gracias al anycast.' },
  { id: 'gc-pause', term: 'Pausa de GC', en: 'Garbage collection pause', cat: 'resiliencia', mods: ['m03', 'm04', 'm06', 'm061'],
    deep: 'm03#algoritmos', aliases: ['pausa de GC', 'pausas de GC', 'pausa larga de GC', 'garbage collector', 'recolector de basura', 'stop-the-world'],
    short: 'Tiempo en que el recolector de basura (garbage collector) del runtime detiene los hilos de la aplicación para liberar memoria. Una pausa larga deja al proceso vivo pero congelado: no responde, aunque no se cayó.' },
  { id: 'health-check', term: 'Health check', en: 'Health check', cat: 'resiliencia', mods: ['m01', 'm03'],
    deep: 'm03#health', basic: true,
    short: 'Prueba periódica (por ejemplo, GET /readyz cada 5 s) con la que un balanceador decide si una instancia puede recibir tráfico.' }
]);

/* ---------- M02: protocolos y APIs ---------- */
SD.defineGlossary([
  { id: 'rest', term: 'REST', en: 'Representational State Transfer', cat: 'redes', mods: ['m02'],
    deep: 'm02#rest', basic: true,
    short: 'Estilo de API sobre HTTP en el que se exponen recursos con URLs y se operan con los métodos estándar (GET, POST, PUT, PATCH, DELETE), aprovechando cachés, códigos de estado y semántica de HTTP.' },
  { id: 'metodo-seguro', term: 'Método seguro e idempotente', en: 'Safe and idempotent methods', cat: 'redes', mods: ['m02'],
    deep: 'm02#rest', aliases: ['método seguro', 'métodos seguros', 'safe method'],
    short: 'Un método es seguro si no cambia nada en el servidor (GET, HEAD) e idempotente si repetirlo deja el mismo estado (GET, PUT, DELETE). POST no es ninguna de las dos cosas.',
    related: ['idempotencia'] },
  { id: 'problem-json', term: 'Problem Details', en: 'application/problem+json (RFC 9457)', cat: 'redes', mods: ['m02'],
    deep: 'm02#errores', aliases: ['problem+json'],
    short: 'Formato estándar para errores de APIs HTTP: un JSON con type, title, status, detail e instance, más los campos propios que necesites.' },
  { id: 'cursor-pagination', term: 'Paginación por cursor', en: 'Cursor / keyset pagination', cat: 'datos', mods: ['m02'],
    deep: 'm02#paginacion', aliases: ['paginación con cursor', 'cursor pagination', 'keyset pagination'],
    short: 'Paginar con un marcador de la última fila vista ("dame los siguientes después de este") en lugar de un OFFSET. Cuesta O(log n + k) a cualquier profundidad y no repite ni saltea filas por inserts arriba o borrados; las filas que aparecen detrás de la marca (commits tardíos) necesitan una ventana de solape.' },
  { id: 'etag', term: 'ETag', en: 'Entity tag', cat: 'redes', mods: ['m02'],
    deep: 'm02#etag',
    short: 'Identificador de versión de un recurso. Sirve para cachés (If-None-Match → 304) y para control de concurrencia optimista (If-Match → 412 si alguien lo cambió antes).' },
  { id: 'grpc', term: 'gRPC', en: 'gRPC Remote Procedure Calls', cat: 'redes', mods: ['m02'],
    deep: 'm02#grpc',
    short: 'Framework de RPC sobre HTTP/2 con contratos en Protocol Buffers: binario, tipado, con streaming en ambos sentidos y deadlines. Habitual entre servicios internos.',
    related: ['protobuf'] },
  { id: 'protobuf', term: 'Protocol Buffers', en: 'Protobuf', cat: 'redes', mods: ['m02'],
    deep: 'm02#protobuf', aliases: ['Protobuf'],
    short: 'Formato binario de serialización con esquema (.proto). Es compacto y rápido, y permite evolucionar mensajes sin romper clientes si se respetan los números de campo.' },
  { id: 'graphql', term: 'GraphQL', en: 'GraphQL', cat: 'redes', mods: ['m02'],
    deep: 'm02#graphql',
    short: 'Lenguaje de consultas para APIs: el cliente pide exactamente los campos y relaciones que necesita en una sola request, contra un esquema tipado.' },
  { id: 'n-mas-1', term: 'Problema N+1', en: 'N+1 query problem', cat: 'datos', mods: ['m02'],
    deep: 'm02#graphql-n1', aliases: ['N+1'],
    short: 'Hacer 1 consulta para una lista y luego N consultas más, una por elemento. En GraphQL se resuelve agrupando las cargas (DataLoader) en una sola consulta por lote.' },
  { id: 'websocket', term: 'WebSocket', en: 'WebSocket', cat: 'redes', mods: ['m02'],
    deep: 'm02#websocket-cable', basic: true,
    short: 'Conexión persistente y bidireccional que empieza como una request HTTP y luego se convierte en un canal de mensajes en ambos sentidos.' },
  { id: 'long-polling', term: 'Long polling', en: 'Long polling', cat: 'redes', mods: ['m02'],
    deep: 'm02#polling', aliases: ['long-polling'],
    short: 'El cliente hace una request que el servidor mantiene abierta hasta que hay algo nuevo (o vence un timeout); al recibir la respuesta, el cliente vuelve a preguntar.' },
  { id: 'webhook', term: 'Webhook', en: 'Webhook', cat: 'redes', mods: ['m02', 'm27'],
    deep: 'm02#webhooks', basic: true,
    short: 'Una request HTTP que tu sistema envía a la URL de un cliente cuando ocurre un evento. La entrega es al menos una vez: el receptor debe verificar la firma y deduplicar.' },
  { id: 'hmac', term: 'HMAC', en: 'Hash-based Message Authentication Code', cat: 'seguridad', mods: ['m02', 'm09', 'm36'],
    deep: 'm36#hmac',
    short: 'Firma calculada con una función hash y un secreto compartido. Quien conoce el secreto puede verificar que el mensaje no fue alterado y que lo generó alguien con ese secreto.' },
  { id: 'deadline', term: 'Deadline', en: 'Deadline propagation', cat: 'resiliencia', mods: ['m02', 'm08'],
    deep: 'm08#deadline-viaje',
    short: 'Momento absoluto en que una request deja de tener sentido. Se propaga a cada llamada interna para que nadie siga trabajando en una respuesta que el usuario ya abandonó.' }
]);

/* ---------- M02: protocolos a fondo ---------- */
SD.defineGlossary([
  { id: 'multiplexar', term: 'Multiplexar', en: 'Multiplexing', cat: 'redes', mods: ['m01', 'm02'],
    deep: 'm01#http-animacion', aliases: ['multiplexación', 'multiplexa', 'multiplexan', 'multiplexado', 'multiplexados', 'multiplexadas', 'multiplexing'],
    short: 'Llevar varias conversaciones independientes por un mismo canal, intercalando sus pedazos y marcando cada uno con la conversación a la que pertenece, para que el otro extremo los vuelva a separar. HTTP/2 multiplexa streams sobre una conexión TCP; QUIC, sobre UDP.',
    related: ['hol-blocking', 'quic'] },
  { id: 'rpc', term: 'RPC', en: 'Remote Procedure Call', cat: 'redes', mods: ['m02'],
    deep: 'm02#rpc', aliases: ['llamada a procedimiento remoto', 'remote procedure call'],
    short: 'Estilo de API en el que el cliente llama a una función que corre en otra máquina como si fuera local. Un stub generado a partir de un contrato serializa los argumentos, los envía y devuelve el resultado.',
    related: ['grpc', 'idl', 'stub'] },
  { id: 'idl', term: 'IDL', en: 'Interface Definition Language', cat: 'redes', mods: ['m02'],
    deep: 'm02#rpc', aliases: ['lenguaje de definición de interfaces'],
    short: 'Lenguaje neutral para describir las funciones y los tipos de una API, del que se genera código para cada lenguaje. Los archivos .proto de Protobuf y los WSDL de SOAP son IDLs.' },
  { id: 'stub', term: 'Stub', en: 'Client/server stub', cat: 'redes', mods: ['m02'],
    deep: 'm02#rpc', noauto: true,
    short: 'Código generado que tiene la misma firma que la función remota. El del cliente serializa los argumentos y los envía; el del servidor los deserializa y llama a la función real.' },
  { id: 'marshalling', term: 'Marshalling', en: 'Marshalling / serialization', cat: 'redes', mods: ['m02'],
    deep: 'm02#rpc', aliases: ['unmarshalling'],
    short: 'Convertir los argumentos de una llamada en bytes con un formato que los dos lados entienden (Protobuf, XDR, XML, JSON), y el proceso inverso al recibirlos.' },
  { id: 'trailers', term: 'Trailers', en: 'HTTP trailers', cat: 'redes', mods: ['m02'],
    deep: 'm02#grpc', aliases: ['trailers HTTP'],
    short: 'Headers que se envían después del cuerpo de una respuesta HTTP. gRPC pone ahí grpc-status, porque el resultado de una llamada con streaming se conoce recién al final.' },
  { id: 'varint', term: 'Varint', en: 'Variable-length integer', cat: 'redes', mods: ['m02'],
    deep: 'm02#protobuf', aliases: ['varints'],
    short: 'Entero codificado en grupos de 7 bits, donde el bit alto de cada byte dice si sigue otro. Los números chicos ocupan un byte; 150 se escribe 96 01.' },
  { id: 'soap', term: 'SOAP', en: 'SOAP', cat: 'redes', mods: ['m02'],
    deep: 'm02#soap',
    short: 'Protocolo de mensajes en XML con un sobre (Envelope) de cabecera y cuerpo, contratos en WSDL y extensiones estándar como WS-Security. SOAP 1.2 es recomendación del W3C desde 2003.',
    related: ['wsdl', 'ws-security'] },
  { id: 'wsdl', term: 'WSDL', en: 'Web Services Description Language', cat: 'redes', mods: ['m02'],
    deep: 'm02#wsdl',
    short: 'Documento XML que describe un servicio SOAP: tipos, operaciones, mensajes de error, codificación y dirección. Las herramientas generan los stubs a partir de él.' },
  { id: 'ws-security', term: 'WS-Security', en: 'Web Services Security', cat: 'seguridad', mods: ['m02'],
    deep: 'm02#soap-seguridad',
    short: 'Estándar de OASIS (2004) para firmar y cifrar partes de un mensaje SOAP, con tokens de identidad y un timestamp. La protección viaja con el mensaje, a través de cualquier intermediario.',
    related: ['no-repudio', 'xml-signature-wrapping'] },
  { id: 'no-repudio', term: 'No repudio', en: 'Non-repudiation', cat: 'seguridad', mods: ['m02', 'm36'],
    deep: 'm36#firmas', aliases: ['non-repudiation'],
    short: 'Garantía de que quien envió un mensaje no puede negarlo después: el mensaje va firmado con una clave privada que solo tiene el emisor, y la firma se puede verificar mientras se guarde el mensaje.' },
  { id: 'xml-signature-wrapping', term: 'XML Signature Wrapping', en: 'XML Signature Wrapping (XSW)', cat: 'seguridad', mods: ['m02'],
    deep: 'm02#soap-seguridad', aliases: ['signature wrapping'],
    short: 'Ataque que mueve la parte firmada de un XML a otro lugar y pone contenido falso donde la aplicación lo va a leer: la firma verifica bien, pero la aplicación procesa otra cosa.' },
  { id: 'xxe', term: 'XXE', en: 'XML External Entity', cat: 'seguridad', mods: ['m02'],
    deep: 'm02#soap-seguridad',
    short: 'Ataque que usa una entidad externa de XML para que el parser lea un archivo local o una URL interna y la incluya en el documento. Se evita desactivando las DTD y las entidades externas.' },
  { id: 'json-rpc', term: 'JSON-RPC', en: 'JSON-RPC 2.0', cat: 'redes', mods: ['m02'],
    deep: 'm02#estilos',
    short: 'Protocolo de RPC mínimo en JSON: method, params e id, con códigos de error estándar y notificaciones sin respuesta. Lo usan el Language Server Protocol y el Model Context Protocol.' },
  { id: 'hateoas', term: 'HATEOAS', en: 'Hypermedia as the Engine of Application State', cat: 'redes', mods: ['m02'],
    deep: 'm02#rest-fielding', aliases: ['modelo de madurez de Richardson'],
    short: 'Restricción de REST según la cual las respuestas traen enlaces a las acciones posibles y el cliente navega por ellos en lugar de construir URLs. Es el nivel 3 del modelo de madurez de Richardson.' },
  { id: 'dataloader', term: 'DataLoader', en: 'DataLoader', cat: 'datos', mods: ['m02'],
    deep: 'm02#graphql-n1',
    short: 'Utilidad que junta las cargas por id pedidas en el mismo turno del event loop en una sola consulta, y las cachea durante la request. Es la solución estándar al problema N+1 en GraphQL.',
    related: ['n-mas-1'] },
  { id: 'persisted-query', term: 'Persisted query', en: 'Persisted query', cat: 'redes', mods: ['m02'],
    deep: 'm02#graphql-cache', aliases: ['persisted queries', 'consultas persistidas'],
    short: 'Consulta de GraphQL registrada de antemano y enviada por su hash. Permite usar GET y caché de CDN, y, si el servidor solo acepta las registradas, cierra la puerta a consultas arbitrarias.' },
  { id: 'graphql-federation', term: 'Federación de GraphQL', en: 'GraphQL federation', cat: 'redes', mods: ['m02'],
    deep: 'm02#graphql-cache', aliases: ['GraphQL federation'],
    short: 'Cada equipo publica una parte del esquema (un subgrafo) y un router las compone en un solo grafo, planifica cada consulta y reparte los pedazos entre los subgrafos.' }
]);

/* ---------- M03: balanceo, gateways y proxies ---------- */
SD.defineGlossary([
  { id: 'reverse-proxy', term: 'Proxy inverso', en: 'Reverse proxy', cat: 'redes', mods: ['m03'],
    deep: 'm03#capas', basic: true,
    short: 'Servidor que recibe las requests en nombre de tus servicios y las reenvía hacia ellos. Los clientes solo ven al proxy.' },
  { id: 'l4-l7', term: 'Balanceo L4 y L7', en: 'Layer 4 / Layer 7 load balancing', cat: 'redes', mods: ['m03'],
    deep: 'm03#l4-l7', aliases: ['L4/L7', 'L4', 'L7'],
    short: 'L4 decide por conexión mirando IPs y puertos, sin entender el contenido. L7 decide por request entendiendo HTTP: path, headers, cookies.' },
  { id: 'least-conn', term: 'Menos conexiones', en: 'Least connections / least outstanding requests', cat: 'resiliencia', mods: ['m03'],
    deep: 'm03#algoritmos', aliases: ['least connections', 'least-conn', 'least outstanding requests'],
    short: 'Algoritmo de balanceo que envía cada request al backend con menos trabajo en curso. Esquiva solo a los servidores lentos.' },
  { id: 'p2c', term: 'Power of two choices', en: 'P2C', cat: 'resiliencia', mods: ['m03', 'm19'],
    deep: 'm03#algoritmos', aliases: ['P2C'],
    short: 'Elegir dos backends al azar y enviar la request al menos cargado de los dos. Casi tan bueno como mirar todos, sin necesitar estado global.' },
  { id: 'consistent-hashing', term: 'Hashing consistente', en: 'Consistent hashing', cat: 'distribuidos', mods: ['m03', 'm05', 'm19'],
    deep: 'm05#rebalanceo', aliases: ['consistent hashing', 'hash consistente'],
    short: 'Asignar claves a nodos sobre un anillo de hashes, de modo que al agregar o quitar un nodo solo se mueve una fracción pequeña (≈ 1/N) de las claves.' },
  { id: 'sticky-session', term: 'Sticky session', en: 'Session affinity', cat: 'redes', mods: ['m03'],
    deep: 'm03#sticky', aliases: ['afinidad de sesión'],
    short: 'Enviar siempre al mismo usuario al mismo backend, con una cookie del balanceador o un hash de la IP. Existe para servidores que guardan la sesión en su propia memoria; rompe el balanceo y la tolerancia a fallas, y sacar el estado a un almacén compartido lo vuelve un SPOF que hay que replicar.' },
  { id: 'api-gateway', term: 'API gateway', en: 'API gateway', cat: 'redes', mods: ['m03'],
    deep: 'm03#gateway',
    short: 'Punto de entrada único a tus APIs que resuelve lo transversal: autenticación, rate limiting, enrutamiento, cuotas, transformación y observabilidad.' },
  { id: 'bff', term: 'BFF', en: 'Backend for Frontend', cat: 'redes', mods: ['m03'],
    deep: 'm03#bff', aliases: ['Backend for Frontend', 'backends for frontends'],
    short: 'Un backend específico para una experiencia de cliente (web, móvil, TV), mantenido por el equipo de ese cliente, que compone varias llamadas internas en una respuesta a la medida de esa pantalla. Sabe qué cliente tiene enfrente porque cada uno llama a su propio BFF.' },
  { id: 'service-mesh', term: 'Service mesh', en: 'Service mesh', cat: 'redes', mods: ['m03'],
    deep: 'm03#mesh',
    short: 'Capa de red entre servicios formada por proxies (sidecars) junto a cada instancia, configurados desde un plano de control: mTLS, reintentos, timeouts y métricas sin tocar el código.' },
  { id: 'sidecar', term: 'Sidecar', en: 'Sidecar proxy', cat: 'redes', mods: ['m03'],
    deep: 'm03#mesh',
    short: 'Proceso que corre al lado de cada instancia de tu servicio e intercepta su tráfico de red (por ejemplo, Envoy en Istio).' },
  { id: 'outlier-detection', term: 'Detección de outliers', en: 'Outlier detection / passive health checking', cat: 'resiliencia', mods: ['m03'],
    deep: 'm03#health', aliases: ['outlier detection'],
    short: 'Sacar temporalmente de rotación a un backend que devuelve errores o tarda mucho con tráfico real, sin esperar al health check activo.' },
  { id: 'draining', term: 'Connection draining', en: 'Connection draining', cat: 'resiliencia', mods: ['m03', 'm19'],
    deep: 'm03#health', aliases: ['drenaje de conexiones', 'drenaje'],
    short: 'Al retirar una instancia, dejar de enviarle requests nuevas pero esperar a que terminen las que tiene en curso.' }
]);

/* ---------- M04: caché ---------- */
SD.defineGlossary([
  { id: 'cache-aside', term: 'Cache-aside', en: 'Lazy loading', cat: 'datos', mods: ['m04'],
    deep: 'm04#patrones', aliases: ['cache aside'],
    short: 'La aplicación busca primero en la caché; si no está, lee la fuente de verdad y guarda el resultado en la caché con un TTL. La caché no sabe nada de la base.' },
  { id: 'write-through', term: 'Write-through', en: 'Write-through cache', cat: 'datos', mods: ['m04'],
    deep: 'm04#patrones',
    short: 'Cada escritura va a la caché y a la base en la misma operación, así la caché siempre tiene el último valor. Las escrituras son más lentas.' },
  { id: 'write-behind', term: 'Write-behind', en: 'Write-back cache', cat: 'datos', mods: ['m04'],
    deep: 'm04#patrones', aliases: ['write-back'],
    short: 'Las escrituras van a la caché y se vuelcan a la base después, en lote. Muy rápido, pero si la caché muere antes de volcar, se pierden datos confirmados.' },
  { id: 'hit-ratio', term: 'Tasa de acierto', en: 'Hit ratio', cat: 'datos', mods: ['m04'],
    deep: 'm04#niveles', aliases: ['tasa de aciertos', 'hit ratio', 'hit rate'],
    short: 'Fracción de lecturas que la caché resuelve. Pasar de 95 % a 99 % divide por 5 la carga que llega a la base: los últimos puntos valen mucho.' },
  { id: 'single-flight', term: 'Single-flight', en: 'Request coalescing', cat: 'resiliencia', mods: ['m04'],
    deep: 'm04#stampede', aliases: ['singleflight', 'request coalescing'],
    short: 'Si varias requests piden a la vez la misma clave que falta en caché, solo una la calcula y las demás esperan ese mismo resultado.' },
  { id: 'lease', term: 'Lease', en: 'Lease', cat: 'distribuidos', mods: ['m04', 'm06', 'm061'],
    deep: 'm061#leases',
    short: 'Permiso con vencimiento que da a un cliente el derecho exclusivo de hacer algo (recalcular una clave, ser líder). Si el cliente muere, el permiso vence solo.' },
  { id: 'xfetch', term: 'Expiración anticipada probabilística', en: 'Probabilistic early expiration (XFetch)', cat: 'datos', mods: ['m04'],
    deep: 'm04#stampede', aliases: ['XFetch', 'expiración anticipada'],
    short: 'Cada lectura cercana al vencimiento de una clave tiene una pequeña probabilidad, creciente, de recalcularla antes de tiempo. Así casi siempre se renueva antes de vencer y no hay estampida.' },
  { id: 'hot-key', term: 'Clave caliente', en: 'Hot key', cat: 'datos', mods: ['m04', 'm30'],
    deep: 'm04#hot-keys', aliases: ['claves calientes', 'hot key'],
    short: 'Una clave que recibe una parte desproporcionada del tráfico y satura al único shard que la guarda. Se mitiga con caché local, réplicas de la clave o réplicas de lectura.' },
  { id: 'eviction', term: 'Política de evicción', en: 'Eviction policy', cat: 'datos', mods: ['m04'],
    deep: 'm04#eviccion', aliases: ['evicción', 'políticas de evicción', 'eviction'],
    short: 'Qué expulsa la caché cuando se llena: lo menos usado recientemente (LRU), lo menos usado en frecuencia (LFU) o lo que vence antes (TTL).' },
  { id: 'cdc', term: 'CDC', en: 'Change Data Capture', cat: 'datos', mods: ['m04', 'm07'],
    deep: 'm07#outbox', aliases: ['change data capture'],
    short: 'Leer el log de cambios de una base de datos (el WAL o el binlog) y publicar cada inserción, actualización o borrado como un evento, sin tocar la aplicación que escribe.' },
  { id: 'swr', term: 'Stale-while-revalidate', en: 'Stale-while-revalidate', cat: 'datos', mods: ['m04'],
    deep: 'm04#stampede',
    short: 'Servir la copia vencida de inmediato y actualizarla en segundo plano. El usuario nunca espera el recálculo, a cambio de ver datos algo viejos por un momento.' }
]);

/* ---------- M05: bases de datos ---------- */
SD.defineGlossary([
  { id: 'acid', term: 'ACID', en: 'Atomicity, Consistency, Isolation, Durability', cat: 'datos', mods: ['m05'],
    deep: 'm05#transacciones',
    short: 'Garantías de una transacción: se aplica entera o nada (atomicidad), respeta las reglas (consistencia), no ve a medias a las demás (aislamiento) y sobrevive a un corte una vez confirmada (durabilidad).' },
  { id: 'wal', term: 'WAL', en: 'Write-Ahead Log', cat: 'datos', mods: ['m05'],
    deep: 'm05#almacenamiento', aliases: ['write-ahead log'],
    short: 'Log donde la base anota cada cambio antes de aplicarlo. Si se corta la luz, reproduce el log al arrancar. También es la base de la replicación y del CDC.' },
  { id: 'btree', term: 'B-tree', en: 'B-tree', cat: 'datos', mods: ['m05'],
    deep: 'm05#almacenamiento', aliases: ['B+tree'],
    short: 'Estructura de índice en árbol balanceado con páginas ordenadas: encuentra cualquier clave en 3 o 4 saltos y recorre rangos en orden. Es el índice por defecto de las bases relacionales.' },
  { id: 'lsm', term: 'LSM-tree', en: 'Log-Structured Merge-tree', cat: 'datos', mods: ['m05'],
    deep: 'm05#almacenamiento', aliases: ['LSM'],
    short: 'Motor de almacenamiento que escribe primero en memoria y vuelca archivos inmutables ordenados, que luego compacta. Absorbe muchísimas escrituras a costa de lecturas algo más caras.' },
  { id: 'isolation', term: 'Nivel de aislamiento', en: 'Isolation level', cat: 'datos', mods: ['m05'],
    deep: 'm05#tx-niveles', aliases: ['niveles de aislamiento', 'isolation level'],
    short: 'Qué anomalías entre transacciones concurrentes permite la base: read committed, repeatable read (snapshot) o serializable. Más aislamiento, más bloqueos o abortos.' },
  { id: 'write-skew', term: 'Write skew', en: 'Write skew', cat: 'datos', mods: ['m05'],
    deep: 'm05#tx-niveles',
    short: 'Anomalía en la que dos transacciones leen lo mismo, deciden según eso y escriben filas distintas, violando juntas una regla. Snapshot isolation no la evita; serializable sí.' },
  { id: 'replication-lag', term: 'Retraso de replicación', en: 'Replication lag', cat: 'distribuidos', mods: ['m05'],
    deep: 'm05#read-your-writes', aliases: ['replication lag', 'lag de replicación'],
    short: 'Cuánto va detrás una réplica asíncrona del líder. Causa que un usuario no vea su propia escritura si la lectura va a una réplica atrasada.' },
  { id: 'read-your-writes', term: 'Read-your-writes', en: 'Read-your-writes consistency', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm05#read-your-writes', aliases: ['read your writes'],
    short: 'Garantía de que un usuario siempre ve sus propias escrituras, aunque otros las vean más tarde.' },
  { id: 'sharding', term: 'Sharding', en: 'Partitioning / sharding', cat: 'datos', mods: ['m05'],
    deep: 'm05#sharding', aliases: ['shard'],
    short: 'Repartir los datos de una tabla entre varias máquinas según una clave, para que cada una guarde y atienda solo una parte.',
    related: ['partition-key', 'consistent-hashing'] },
  { id: 'vnodes', term: 'Nodos virtuales', en: 'Virtual nodes', cat: 'distribuidos', mods: ['m05'],
    deep: 'm05#rebalanceo', aliases: ['nodo virtual', 'vnodes'],
    short: 'Poner cada nodo físico en muchas posiciones del anillo de hashing para que la carga se reparta pareja y, al salir un nodo, su parte se reparta entre todos.' },
  { id: 'leaderless', term: 'Replicación sin líder', en: 'Leaderless (Dynamo-style) replication', cat: 'distribuidos', mods: ['m05'],
    deep: 'm05#replicacion', aliases: ['leaderless'],
    short: 'Cualquier réplica acepta escrituras; el cliente escribe en W réplicas y lee de R. Con W + R > N las lecturas ven la última escritura. Usada por Cassandra y DynamoDB.' },
  { id: 'fencing', term: 'Fencing token', en: 'Fencing token', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#leases',
    short: 'Número creciente que acompaña a cada líder o lock. El almacenamiento rechaza escrituras con un número menor al último visto, así un líder viejo que "despierta" no puede corromper nada.' }
]);

/* ---------- M06: teoría distribuida ---------- */
SD.defineGlossary([
  { id: 'linearizable', term: 'Linealizabilidad', en: 'Linearizability', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#linealizabilidad', aliases: ['linealizable', 'linealizables', 'linearizable', 'linearizability'],
    short: 'El modelo de consistencia más fuerte: el sistema se comporta como si hubiera una sola copia y cada operación ocurriera en un instante entre su inicio y su fin. Lo que alguien leyó, nadie lo "desve" después.' },
  { id: 'eventual', term: 'Consistencia eventual', en: 'Eventual consistency', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm06#consistencia', aliases: ['eventualmente consistente', 'eventual consistency'],
    short: 'Si dejan de llegar escrituras, tarde o temprano todas las réplicas convergen al mismo valor. No dice cuándo ni qué ves mientras tanto.' },
  { id: 'causal', term: 'Consistencia causal', en: 'Causal consistency', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm06#consistencia', aliases: ['causal consistency'],
    short: 'Si una operación pudo influir en otra (una respuesta a un mensaje), todos las ven en ese orden. Las operaciones sin relación pueden verse en distinto orden.' },
  { id: 'lamport', term: 'Reloj de Lamport', en: 'Lamport clock', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#happens-before', aliases: ['relojes de Lamport', 'Lamport clock'],
    short: 'Contador que cada nodo incrementa en cada evento y ajusta al máximo recibido en cada mensaje. Da un orden total compatible con la causalidad, sin relojes físicos.' },
  { id: 'vector-clock', term: 'Reloj vectorial', en: 'Vector clock', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#happens-before', aliases: ['relojes vectoriales', 'vector clock'],
    short: 'Un contador por nodo. Comparando dos vectores se sabe si un evento ocurrió antes que otro o si fueron concurrentes, que es lo que hace falta para detectar conflictos.' },
  { id: 'hlc', term: 'Hybrid Logical Clock', en: 'HLC', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#hlc-truetime', aliases: ['HLC'],
    short: 'Reloj que combina el tiempo físico con un contador lógico: timestamps cercanos a la hora real y que igual respetan la causalidad. Lo usa CockroachDB.' },
  { id: 'truetime', term: 'TrueTime', en: 'TrueTime', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#hlc-truetime',
    short: 'API de relojes de Google Spanner que devuelve un intervalo [más temprano, más tarde] con la incertidumbre acotada por GPS y relojes atómicos. Spanner espera a que pase la incertidumbre antes de confirmar.' },
  { id: 'raft', term: 'Raft', en: 'Raft consensus algorithm', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#consenso',
    short: 'Algoritmo de consenso diseñado para ser entendible: un líder elegido por mayoría replica un log; una entrada se confirma cuando la tiene una mayoría. Lo usan etcd, Consul y CockroachDB.' },
  { id: 'paxos', term: 'Paxos', en: 'Paxos', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#paxos',
    short: 'La familia original de algoritmos de consenso (Lamport). Garantiza seguridad con fallas por caída; Multi-Paxos agrega un líder estable. Es la base de Chubby y Spanner.' },
  { id: 'flp', term: 'Imposibilidad FLP', en: 'FLP impossibility', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#imposibles', aliases: ['FLP'],
    short: 'Teorema de Fischer, Lynch y Paterson (1985): en un sistema totalmente asíncrono, ningún algoritmo determinista garantiza llegar a consenso si puede caer aunque sea un nodo.' },
  { id: 'two-generals', term: 'Problema de los dos generales', en: 'Two Generals problem', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#imposibles', aliases: ['dos generales', 'two generals'],
    short: 'Dos partes que se comunican por un canal que puede perder mensajes no pueden estar nunca seguras de haber acordado algo. Por eso no existe la entrega "exactamente una vez" por la red.' },
  { id: 'pbft', term: 'PBFT', en: 'Practical Byzantine Fault Tolerance', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#bizantinas',
    short: 'Algoritmo de consenso de Castro y Liskov (1999) que tolera f nodos bizantinos con 3f + 1 réplicas, a costa de muchos más mensajes que Raft o Paxos.' },
  { id: 'split-brain', term: 'Split brain', en: 'Split brain', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#leases', aliases: ['split-brain', 'cerebro dividido'],
    short: 'Cuando una partición deja a dos partes del sistema creyendo, cada una, que es la que manda, y ambas aceptan escrituras incompatibles.' },
  /* M06 ampliado: modelo, detectores, consistencia, quórums, relojes, consenso, transacciones, CRDTs, verificación */
  { id: 'modelo-sistema', term: 'Modelo de sistema', en: 'System model', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#modelo', aliases: ['modelos de sistema', 'system model'],
    short: 'Los supuestos con los que se razona un sistema distribuido: cuánto pueden tardar los mensajes (síncrono, asíncrono o parcialmente síncrono) y de qué formas puede fallar un nodo (caída, omisión, bizantina). Un algoritmo correcto en un modelo puede fallar en otro.',
    related: ['sincronia-parcial', 'crash-recovery'] },
  { id: 'sincronia-parcial', term: 'Sincronía parcial', en: 'Partial synchrony', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#modelo-tiempo', aliases: ['parcialmente síncrono', 'parcialmente síncrona', 'partial synchrony', 'GST'],
    short: 'Modelo de Dwork, Lynch y Stockmeyer (1988): el sistema puede portarse de forma asíncrona durante un tiempo, pero desde un instante desconocido (GST) los mensajes llegan dentro de una cota. Raft y Paxos son seguros siempre y progresan después de GST.',
    related: ['flp', 'modelo-sistema'] },
  { id: 'crash-recovery', term: 'Crash-recovery', en: 'Crash-recovery failure model', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#modelo-fallas', aliases: ['crash-stop', 'caída y recuperación'],
    short: 'Modelo de fallas en el que un nodo se cae y vuelve con lo que había persistido en disco, sin lo que tenía en memoria. Obliga a guardar en disco (fsync) todo lo prometido antes de responder.',
    related: ['modelo-sistema'] },
  { id: 'safety-liveness', term: 'Safety y liveness', en: 'Safety and liveness properties', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#safety-liveness', aliases: ['propiedad de safety', 'propiedades de safety', 'propiedad de liveness', 'propiedades de liveness'],
    short: 'Las dos clases de propiedades de un sistema. Safety: nunca pasa nada malo (dos líderes, un dato corrupto), y se viola en un instante concreto. Liveness: algo bueno termina pasando (toda request recibe respuesta), y nunca se puede refutar en un tiempo finito.' },
  { id: 'failure-detector', term: 'Detector de fallas', en: 'Failure detector', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#detectores', aliases: ['detectores de fallas', 'failure detector'],
    short: 'Componente que sospecha que un nodo cayó después de cierto silencio. En un sistema asíncrono no puede distinguir un nodo caído de uno lento, así que siempre puede equivocarse: la corrección de los datos no debe depender de él.',
    related: ['phi-accrual', 'swim'] },
  { id: 'phi-accrual', term: 'Phi accrual', en: 'φ accrual failure detector', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#phi-accrual', aliases: ['phi accrual'],
    short: 'Detector de fallas que, en lugar de un timeout fijo, calcula qué tan improbable es el silencio actual según la historia de heartbeats del nodo (φ = −log₁₀ de esa probabilidad). Cassandra y Akka lo usan con un umbral de 8.',
    related: ['failure-detector'] },
  { id: 'swim', term: 'SWIM', en: 'Scalable Weakly-consistent Infection-style Membership', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#swim',
    short: 'Protocolo de membresía y detección de fallas (2002): cada nodo prueba a uno al azar por período, pide pruebas indirectas a otros antes de sospechar y difunde los cambios por gossip. Lo implementa memberlist, la biblioteca de HashiCorp que usa Consul.',
    related: ['gossip', 'failure-detector'] },
  { id: 'gossip', term: 'Gossip', en: 'Gossip / epidemic protocol', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#swim', aliases: ['difusión epidémica', 'protocolo de gossip', 'protocolos de gossip'],
    short: 'Difusión epidémica: cada nodo les cuenta las novedades a unos pocos nodos al azar, que hacen lo mismo, y en O(log n) rondas lo sabe todo el clúster. Se usa para la membresía y el estado en Cassandra, Consul y muchos sistemas sin coordinador.',
    related: ['swim'] },
  { id: 'harvest-yield', term: 'Harvest y yield', en: 'Harvest and yield', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#cap-matices', aliases: ['harvest y yield'],
    short: 'Dos medidas de la degradación (Fox y Brewer, 1999): el yield es la fracción de requests que reciben respuesta; el harvest, la fracción de los datos que refleja cada respuesta. Un buscador con un shard caído puede responder todo con resultados incompletos.',
    related: ['cap'] },
  { id: 'secuencial', term: 'Consistencia secuencial', en: 'Sequential consistency', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#secuencial', aliases: ['sequential consistency', 'secuencialmente consistente'],
    short: 'Modelo de Lamport (1979): todas las operaciones parecen ocurrir en un único orden que respeta el orden de cada cliente, pero no el tiempo real entre clientes distintos. Es más débil que la linealizabilidad, que sí lo respeta.',
    related: ['linearizable'] },
  { id: 'session-guarantees', term: 'Garantías de sesión', en: 'Session guarantees', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#sesion', aliases: ['garantía de sesión', 'lecturas monótonas', 'lectura monótona', 'monotonic reads', 'session guarantees'],
    short: 'Garantías que se le dan a cada cliente sobre sus propias operaciones: read-your-writes, lecturas monótonas, escrituras monótonas y escrituras después de lecturas (Terry y otros, 1994). Se implementan con un token de versión, sin coordinación global.',
    related: ['read-your-writes', 'causal'] },
  { id: 'strict-serializability', term: 'Serializabilidad estricta', en: 'Strict serializability', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#serializable', aliases: ['serializable estricta', 'serializables estrictas', 'serializable estricto', 'serializables estrictos', 'strict serializability', 'strict serializable', 'consistencia externa', 'external consistency'],
    short: 'Transacciones serializables cuyo orden además respeta el tiempo real: si una confirmó antes de que otra empezara, va antes. Es serializable más linealizable; Spanner la llama consistencia externa.',
    related: ['linearizable', 'isolation'] },
  { id: 'abd', term: 'ABD', en: 'Attiya, Bar-Noy y Dolev (1995)', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#quorum-lin',
    short: 'Algoritmo que da un registro linealizable sobre quórums: antes de responder, el lector escribe en un quórum el valor más nuevo que encontró, para que nadie lea después un valor más viejo.',
    related: ['quorum', 'linearizable'] },
  { id: 'hinted-handoff', term: 'Hinted handoff', en: 'Hinted handoff', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#sloppy',
    short: 'Cuando una réplica está caída, otro nodo guarda sus escrituras con una pista de a quién pertenecen y se las entrega cuando vuelve. Mejora la disponibilidad de escritura en las bases estilo Dynamo.',
    related: ['sloppy-quorum'] },
  { id: 'sloppy-quorum', term: 'Sloppy quorum', en: 'Sloppy quorum', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#sloppy',
    short: 'Quórum que, si fallan réplicas, acepta escrituras en otros nodos sanos en lugar de los N de siempre. Mejora la disponibilidad, pero W + R > N deja de garantizar que una lectura vea la última escritura.',
    related: ['quorum', 'hinted-handoff'] },
  { id: 'flexible-paxos', term: 'Flexible Paxos', en: 'Flexible Paxos', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#quorums-flexibles', aliases: ['quórums flexibles', 'quórum flexible'],
    short: 'Resultado de Howard, Malkhi y Spiegelman (2016): en Paxos solo tienen que solaparse los quórums de elección con los de replicación, no los de replicación entre sí. Permite replicar en pocos nodos a cambio de elecciones más caras.',
    related: ['paxos', 'quorum'] },
  { id: 'happens-before', term: 'Happens-before', en: 'Happens-before relation', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#happens-before',
    short: 'Relación de Lamport (1978): a ocurrió antes que b si van en ese orden en un mismo proceso, si a es el envío de un mensaje y b su recepción, o por una cadena de esos pasos. Si ninguno ocurrió antes que el otro, son concurrentes.',
    related: ['lamport', 'vector-clock'] },
  { id: 'commit-wait', term: 'Commit wait', en: 'Commit wait', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#hlc-truetime',
    short: 'Técnica de Spanner: al confirmar, esperar a que pase la incertidumbre de TrueTime (unos milisegundos), para que toda transacción posterior, en cualquier lugar, reciba un timestamp mayor. Así logra consistencia externa.',
    related: ['truetime'] },
  { id: 'smr', term: 'Replicación de máquina de estados', en: 'State machine replication', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#consenso', aliases: ['replicación de máquinas de estados', 'state machine replication'],
    short: 'Replicar un servicio haciendo que todas las réplicas apliquen las mismas operaciones en el mismo orden, decidido por consenso sobre un log. Si arrancan iguales, terminan iguales. Así funcionan etcd y ZooKeeper.',
    related: ['consenso', 'raft'] },
  { id: 'atomic-broadcast', term: 'Difusión atómica', en: 'Atomic (total order) broadcast', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#consenso', aliases: ['atomic broadcast', 'total order broadcast'],
    short: 'Entregar los mismos mensajes, en el mismo orden, a todos los nodos correctos. Es equivalente al consenso repetido: con uno se construye el otro.',
    related: ['consenso'] },
  { id: 'read-index', term: 'ReadIndex', en: 'Raft ReadIndex', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#raft-lecturas',
    short: 'Forma de servir lecturas linealizables en Raft sin escribirlas en el log: el líder anota su índice de commit, confirma con un heartbeat a la mayoría que sigue siendo líder y responde cuando aplicó hasta ese índice. etcd la usa por defecto.',
    related: ['raft', 'linearizable'] },
  { id: 'joint-consensus', term: 'Joint consensus', en: 'Joint consensus', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#raft-membresia',
    short: 'Forma de cambiar los miembros de un clúster de Raft pasando por una configuración conjunta, en la que toda decisión necesita mayoría en la vieja y en la nueva, para que nunca convivan dos mayorías disjuntas.',
    related: ['raft'] },
  { id: 'prevote', term: 'PreVote y CheckQuorum', en: 'Raft PreVote and CheckQuorum', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#raft-operacion', aliases: ['PreVote', 'Pre-Vote', 'CheckQuorum'],
    short: 'Dos extensiones de Raft para cortes de red. Con PreVote, un candidato pregunta si ganaría antes de incrementar el término, así un nodo aislado no depone al líder al volver; con CheckQuorum, un líder que no escucha a una mayoría renuncia. Juntas evitan elecciones sin fin.',
    related: ['raft'] },
  { id: 'multi-paxos', term: 'Multi-Paxos', en: 'Multi-Paxos', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#multi-paxos', aliases: ['MultiPaxos'],
    short: 'Paxos para un log: un líder estable hace la fase de preparación una vez para todos los índices futuros, y cada valor nuevo cuesta una sola ronda hasta una mayoría. Raft es, en esencia, una variante.',
    related: ['paxos', 'raft'] },
  { id: 'two-phase-commit', term: 'Two-phase commit', en: 'Two-phase commit (2PC)', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#two-phase-commit', aliases: ['2PC', 'commit en dos fases'],
    short: 'Protocolo de compromiso atómico: un coordinador les pide a los participantes que se preparen y voten, y si todos votan sí, ordena confirmar. Si el coordinador cae después de la votación, los participantes quedan bloqueados con los locks tomados.',
    related: ['saga', 'percolator'] },
  { id: 'percolator', term: 'Percolator', en: 'Percolator (Google, 2010)', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#percolator',
    short: 'Sistema de transacciones de Google sobre Bigtable: los cambios se escriben con locks que apuntan a una fila primaria, y el commit es una sola escritura en esa fila. Da snapshot isolation; TiDB usa el mismo modelo.',
    related: ['two-phase-commit'] },
  { id: 'lww', term: 'Last-write-wins', en: 'Last-write-wins (LWW)', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#crdt', aliases: ['LWW', 'last write wins'],
    short: 'Resolución de conflictos en la que gana la escritura con el timestamp más alto. Es simple, pero descarta en silencio las escrituras concurrentes, y con un reloj adelantado siempre gana el mismo nodo.',
    related: ['crdt', 'vector-clock'] },
  { id: 'read-repair', term: 'Read repair', en: 'Read repair', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#anti-entropia',
    short: 'Al leer de varias réplicas, corregir las que respondieron con una versión vieja. Repara solo lo que se lee; el resto lo cubre la anti-entropía.',
    related: ['anti-entropia'] },
  { id: 'anti-entropia', term: 'Anti-entropía', en: 'Anti-entropy', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#anti-entropia', aliases: ['anti-entropy'],
    short: 'Proceso de fondo en el que dos réplicas comparan lo que tienen, normalmente con árboles de Merkle, y se intercambian solo lo que difiere. Garantiza que converjan aunque nadie lea los datos.',
    related: ['merkle-tree', 'read-repair'] },
  { id: 'merkle-tree', term: 'Árbol de Merkle', en: 'Merkle tree', cat: 'distribuidos', mods: ['m05', 'm06', 'm061'],
    deep: 'm061#anti-entropia', aliases: ['árboles de Merkle', 'Merkle tree'],
    short: 'Árbol de hashes: cada hoja es el hash de un bloque de datos y cada nodo, el hash de sus hijos. Dos réplicas comparan las raíces y bajan solo por las ramas que difieren, así encuentran diferencias entre millones de claves con pocos hashes.',
    related: ['anti-entropia'] },
  { id: 'redlock', term: 'Redlock', en: 'Redlock', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#redlock',
    short: 'Algoritmo de locks distribuidos propuesto para Redis: tomar el lock en la mayoría de varios nodos independientes. Depende de supuestos de tiempo y no entrega fencing tokens, así que no sirve para locks de los que depende la corrección.',
    related: ['fencing', 'lease'] },
  { id: 'stonith', term: 'STONITH', en: 'Shoot the other node in the head', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#redlock',
    short: 'Antes de promover un nodo nuevo, apagar el viejo por su interfaz de administración, para que no pueda seguir escribiendo en un recurso compartido. Es fencing aplicado desde afuera.',
    related: ['fencing', 'split-brain'] },
  { id: 'jepsen', term: 'Jepsen', en: 'Jepsen', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#jepsen',
    short: 'Proyecto de Kyle Kingsbury que prueba bases de datos distribuidas reales inyectando particiones, pausas y saltos de reloj, y verifica la historia de operaciones contra el modelo de consistencia que el sistema promete.',
    related: ['linearizable'] },
  { id: 'tla-plus', term: 'TLA+', en: 'Temporal Logic of Actions', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#tla',
    short: 'Lenguaje de especificación de Lamport que describe un sistema como estados y transiciones. Su model checker recorre todas las ejecuciones de un modelo chico buscando violaciones; AWS lo usó para encontrar bugs en S3 y DynamoDB.',
    related: ['jepsen'] },
  { id: 'simulacion-determinista', term: 'Simulación determinista', en: 'Deterministic simulation testing', cat: 'distribuidos', mods: ['m06', 'm061'],
    deep: 'm061#simulacion', aliases: ['deterministic simulation testing'],
    short: 'Probar un sistema distribuido entero dentro de un solo proceso, con red, discos y relojes simulados y toda la aleatoriedad derivada de una semilla, para inyectar fallas y reproducir cualquier bug exactamente. La popularizó FoundationDB.',
    related: ['jepsen'] }
]);

/* ---------- M07: mensajería asíncrona ---------- */
SD.defineGlossary([
  { id: 'cola', term: 'Cola de mensajes', en: 'Message queue', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#cola-log', basic: true,
    short: 'Buffer donde los productores dejan mensajes y los consumidores los toman; cada mensaje lo procesa un consumidor y se borra al confirmarse. SQS y RabbitMQ son ejemplos.' },
  { id: 'log-distribuido', term: 'Log distribuido', en: 'Distributed log', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#cola-log', aliases: ['logs distribuidos', 'distributed log'],
    short: 'Secuencia de eventos solo de agregado, particionada y replicada, que los consumidores leen a su ritmo guardando su posición (offset). Los eventos no se borran al leerse. Kafka es el ejemplo típico.' },
  { id: 'consumer-group', term: 'Consumer group', en: 'Consumer group', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#kafka',
    short: 'Conjunto de consumidores que se reparten las particiones de un tópico: cada partición la lee un solo miembro. Distintos grupos leen el mismo tópico de forma independiente.' },
  { id: 'offset', term: 'Offset', en: 'Offset', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#kafka', noauto: true,
    short: 'Posición de un evento dentro de una partición. El consumidor guarda hasta qué offset procesó; si se reinicia, sigue desde ahí.' },
  { id: 'consumer-lag', term: 'Lag del consumidor', en: 'Consumer lag', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#kafka', aliases: ['consumer lag'],
    short: 'Cuántos eventos escritos todavía no procesó un consumidor. Es la métrica principal de salud de un sistema asíncrono.' },
  { id: 'at-least-once', term: 'Al menos una vez', en: 'At-least-once delivery', cat: 'distribuidos', mods: ['m07'],
    deep: 'm07#semanticas', aliases: ['at-least-once', 'at least once'],
    short: 'Garantía de que cada mensaje se procesa una o más veces: nunca se pierde, pero puede duplicarse. Combinada con consumidores idempotentes, produce el efecto de "exactamente una vez".' },
  { id: 'dlq', term: 'Dead letter queue', en: 'DLQ', cat: 'resiliencia', mods: ['m07'],
    deep: 'm07#dlq', aliases: ['DLQ'],
    short: 'Cola aparte donde van los mensajes que fallaron demasiadas veces, para que no bloqueen al resto y alguien los revise.' },
  { id: 'poison', term: 'Mensaje envenenado', en: 'Poison message', cat: 'resiliencia', mods: ['m07'],
    deep: 'm07#dlq', aliases: ['mensajes envenenados', 'poison message', 'poison pill'],
    short: 'Un mensaje que hace fallar al consumidor cada vez que lo procesa. Sin límite de reintentos, bloquea la partición o la cola indefinidamente.' },
  { id: 'schema-registry', term: 'Registro de esquemas', en: 'Schema registry', cat: 'datos', mods: ['m07'],
    deep: 'm07#esquemas', aliases: ['schema registry'],
    short: 'Servicio que guarda las versiones del esquema de cada tópico (Avro, Protobuf, JSON Schema) y rechaza cambios incompatibles antes de que rompan a los consumidores.' }
]);

/* ---------- M08: resiliencia ---------- */
SD.defineGlossary([
  { id: 'timeout', term: 'Timeout', en: 'Timeout', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#timeouts', basic: true,
    short: 'Tiempo máximo que se espera una respuesta antes de darla por fallida. Sin timeout, una dependencia lenta retiene hilos y conexiones hasta agotarlos.' },
  { id: 'backoff', term: 'Backoff exponencial', en: 'Exponential backoff', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#reintentos', aliases: ['backoff', 'exponential backoff'],
    short: 'Esperar cada vez más entre reintentos (por ejemplo 0.5 s, 1 s, 2 s, 4 s) para darle tiempo a la dependencia a recuperarse.' },
  { id: 'retry-budget', term: 'Presupuesto de reintentos', en: 'Retry budget', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#reintentos', aliases: ['retry budget'],
    short: 'Límite a la proporción de reintentos respecto de las requests normales (por ejemplo 10 %). Impide que los reintentos multipliquen la carga justo cuando el sistema está mal.' },
  { id: 'bulkhead', term: 'Bulkhead', en: 'Bulkhead', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#breaker',
    short: 'Separar recursos (pools de hilos, conexiones, instancias) por dependencia o por cliente, para que la falla de uno no agote los recursos de todos. Como los compartimentos estancos de un barco.' },
  { id: 'token-bucket', term: 'Token bucket', en: 'Token bucket', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#rate-limiting', aliases: ['cubeta de tokens'],
    short: 'Algoritmo de rate limiting: un balde se recarga con tokens a ritmo fijo hasta una capacidad máxima, y cada request consume uno. Permite ráfagas cortas y limita el promedio.' },
  { id: 'metastable', term: 'Falla metaestable', en: 'Metastable failure', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#tormenta', aliases: ['fallas metaestables', 'metaestable', 'metaestables', 'metastable failure'],
    short: 'Estado en el que un sistema sigue caído aunque la causa original ya desapareció, porque un ciclo de realimentación (reintentos, trabajo desperdiciado, cachés frías) lo mantiene sobrecargado.' },
  { id: 'graceful-degradation', term: 'Degradación elegante', en: 'Graceful degradation', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#degradacion', aliases: ['graceful degradation'],
    short: 'Seguir ofreciendo una versión reducida del servicio cuando algo falla: recomendaciones genéricas en lugar de personalizadas, datos en caché en lugar de frescos.' },
  { id: 'cell-architecture', term: 'Arquitectura celular', en: 'Cell-based architecture', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#celulas', aliases: ['arquitectura de células', 'cell-based architecture'],
    short: 'Dividir el sistema en copias completas e independientes (celdas), cada una atendiendo a una parte de los clientes, para que una falla o un mal deploy afecte solo a una celda.' },
  { id: 'chaos', term: 'Chaos engineering', en: 'Chaos engineering', cat: 'resiliencia', mods: ['m08'],
    deep: 'm08#caos', aliases: ['ingeniería del caos'],
    short: 'Inyectar fallas a propósito y de forma controlada (matar instancias, agregar latencia, cortar una zona) para comprobar que el sistema se comporta como se diseñó.' }
]);

/* ---------- M09: almacenamiento de objetos ---------- */
SD.defineGlossary([
  { id: 'object-storage', term: 'Almacenamiento de objetos', en: 'Object storage', cat: 'datos', mods: ['m09'],
    deep: 'm09#por-que', aliases: ['object storage', 'object store'],
    short: 'Almacén de archivos (objetos) identificados por una clave dentro de un bucket, con una API HTTP simple: PUT, GET, DELETE y listar. Barato, durable y prácticamente ilimitado; S3 es el estándar de facto.' },
  { id: 'presigned', term: 'URL prefirmada', en: 'Presigned URL', cat: 'seguridad', mods: ['m09'],
    deep: 'm09#signed-urls', aliases: ['URLs prefirmadas', 'presigned URL'],
    short: 'URL que incluye una firma HMAC calculada con tus credenciales sobre el método, el objeto y una expiración. Permite a un cliente subir o bajar ese objeto directamente, sin credenciales propias.',
    related: ['signed-url', 'hmac'] },
  { id: 'multipart', term: 'Subida multipart', en: 'Multipart upload', cat: 'datos', mods: ['m09'],
    deep: 'm09#multipart', aliases: ['subidas multipart', 'multipart upload', 'multipart'],
    short: 'Subir un archivo grande en partes independientes (en paralelo y reintentables) que el almacenamiento une al final. En S3, partes de 5 MB a 5 GB, hasta 10 000 partes.' },
  { id: 'content-addressed', term: 'Almacenamiento direccionado por contenido', en: 'Content-addressed storage', cat: 'datos', mods: ['m09'],
    deep: 'm09#claves', aliases: ['direccionado por contenido', 'direccionamiento por contenido', 'content-addressed'],
    short: 'Usar el hash del contenido como clave del objeto. Dos archivos idénticos ocupan un solo objeto (deduplicación) y el contenido nunca cambia bajo una misma clave.' },
  { id: 'lifecycle', term: 'Reglas de ciclo de vida', en: 'Lifecycle rules', cat: 'datos', mods: ['m09'],
    deep: 'm09#multipart', aliases: ['lifecycle rules', 'lifecycle'],
    short: 'Reglas del bucket que mueven objetos a clases más baratas con el tiempo, los borran, o abortan subidas multipart incompletas, sin código propio.' },
  { id: 'hotlinking', term: 'Hotlinking', en: 'Hotlinking', cat: 'edge', mods: ['m09'],
    deep: 'm09#cdn-protegida', aliases: ['hotlink'],
    short: 'Usar desde otro sitio, o fuera de tu app, las URLs de archivos servidos por tu CDN. Tú pagas el ancho de banda y tu dominio reparte contenido que no controlas. Se frena con URLs firmadas que vencen y con headers como Cross-Origin-Resource-Policy.',
    related: ['presigned', 'cdn'] },
  { id: 'corp', term: 'Cross-Origin-Resource-Policy', en: 'Cross-Origin-Resource-Policy (CORP)', cat: 'seguridad', mods: ['m09'],
    deep: 'm09#hotlinking-alternativas', aliases: ['CORP'],
    short: 'Header de respuesta que le dice al navegador desde qué sitios se puede cargar un recurso (same-origin, same-site o cross-origin). Con same-site, una página ajena no puede mostrar tu imagen; no afecta a scripts ni a apps que no son navegadores.',
    related: ['hotlinking'] }
]);

/* ---------- M10: seguridad e identidad ---------- */
SD.defineGlossary([
  { id: 'authn-authz', term: 'Autenticación y autorización', en: 'AuthN / AuthZ', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#basicos', aliases: ['AuthN', 'AuthZ'],
    short: 'Autenticar es comprobar quién eres; autorizar es decidir qué puedes hacer. Un token válido autentica, pero cada acceso a un recurso necesita además su verificación de permisos.' },
  { id: 'jwt', term: 'JWT', en: 'JSON Web Token', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#tokens',
    short: 'Token con un header, un payload de claims (quién, para qué API, hasta cuándo) y una firma, codificados en base64url. Se verifica sin consultar a nadie, pero no se puede revocar antes de que venza.' },
  { id: 'opaque-token', term: 'Token opaco', en: 'Opaque token', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#tokens', aliases: ['tokens opacos', 'opaque token'],
    short: 'Un identificador aleatorio sin significado: para saber a quién pertenece hay que consultarlo en el servidor. Se puede revocar al instante, a costa de una consulta por request.' },
  { id: 'oauth', term: 'OAuth 2.0', en: 'OAuth 2.0', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#oauth', aliases: ['OAuth2', 'OAuth'],
    short: 'Protocolo para que una aplicación obtenga acceso limitado (scopes) a recursos de un usuario en otro servicio, sin conocer su contraseña, mediante tokens emitidos por un servidor de autorización.' },
  { id: 'oidc', term: 'OpenID Connect', en: 'OIDC', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#oauth', aliases: ['OIDC'],
    short: 'Capa de identidad sobre OAuth 2.0: además del access token, entrega un ID token (un JWT) que dice quién es el usuario. Es lo que hay detrás de "Iniciar sesión con Google".' },
  { id: 'pkce', term: 'PKCE', en: 'Proof Key for Code Exchange', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#pkce',
    short: 'Extensión de OAuth en la que el cliente demuestra, al canjear el código, que es el mismo que lo pidió: manda el hash de un secreto al principio (code_challenge) y el secreto original (code_verifier) al canjear. Algoritmo automático de la RFC 7636; evita que un código interceptado sirva de algo.' },
  { id: 'refresh-token', term: 'Refresh token', en: 'Refresh token', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#jwt-stateful', aliases: ['refresh tokens'],
    short: 'Credencial de larga vida que solo el servidor de autorización acepta y que sirve para pedir access tokens nuevos cuando vencen. Se guarda de forma segura, se rota en cada uso y, si uno ya usado reaparece, se revoca toda la sesión por sospecha de robo.' },
  { id: 'mtls', term: 'mTLS', en: 'Mutual TLS', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#servicios',
    short: 'TLS en el que ambos extremos presentan un certificado, así el servidor también sabe con certeza qué servicio lo llama. Es la base de la identidad entre servicios.' },
  { id: 'kms', term: 'KMS', en: 'Key Management Service', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#cifrado',
    short: 'Servicio que guarda claves maestras en hardware seguro y cifra o descifra con ellas sin dejarlas salir nunca, con cada uso autorizado y auditado.' },
  { id: 'envelope', term: 'Envelope encryption', en: 'Envelope encryption', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#cifrado', aliases: ['cifrado de sobre', 'cifrado envolvente'],
    short: 'Cifrar cada dato con una clave de datos propia (DEK) y guardar esa clave cifrada con una clave maestra del KMS (KEK). Permite cifrar volúmenes enormes sin mandarlos al KMS.' },
  { id: 'rls', term: 'Row-level security', en: 'RLS', cat: 'seguridad', mods: ['m05', 'm10'],
    deep: 'm05#rls', aliases: ['RLS'],
    short: 'Política de la base de datos que filtra automáticamente las filas que cada sesión puede ver o modificar (por ejemplo, solo las de su tenant), aunque la consulta olvide el filtro.' },
  { id: 'bola', term: 'BOLA / IDOR', en: 'Broken Object Level Authorization', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#multitenant', aliases: ['BOLA', 'IDOR'],
    short: 'Vulnerabilidad en la que la API verifica que estás autenticado pero no que el objeto pedido (/facturas/123) sea tuyo. Es el riesgo número uno del OWASP API Top 10.' },
  { id: 'ssrf', term: 'SSRF', en: 'Server-Side Request Forgery', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#ataques',
    short: 'Engañar a un servidor para que haga requests a destinos internos (por ejemplo, el endpoint de metadatos de la nube, que entrega credenciales) usando una URL que el atacante controla.' },
  { id: 'bfla', term: 'BFLA', en: 'Broken Function Level Authorization', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#bfla-detalle',
    short: 'Vulnerabilidad en la que el objeto es tuyo pero la acción no debería serlo: llamas a un endpoint de administración o de borrado y la API no comprueba tu rol. Primo de BOLA, que falla sobre el objeto; BFLA falla sobre la función.' },
  { id: 'mass-assignment', term: 'Asignación masiva', en: 'Mass assignment', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#bfla-detalle', aliases: ['mass assignment'],
    short: 'La API vuelca el JSON recibido directo sobre el objeto, y el atacante agrega un campo que no debería poder tocar (por ejemplo "role": "admin"). Se evita con una lista explícita de campos aceptados.' },
  { id: 'crypto-shredding', term: 'Borrado criptográfico', en: 'Crypto-shredding', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#crypto-shredding', aliases: ['crypto-shredding', 'crypto shredding'],
    short: 'Borrar datos que no puedes alcanzar (backups inmutables) destruyendo la clave con que se cifraron: si cada usuario tiene su propia clave, destruirla vuelve ilegibles todas sus copias a la vez.' },
  { id: 'gdpr', term: 'GDPR', en: 'General Data Protection Regulation', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#crypto-shredding', aliases: ['RGPD'],
    short: 'Reglamento europeo de protección de datos. Da a las personas derechos sobre sus datos personales, entre ellos el derecho al borrado ("derecho al olvido"), que obliga a diseñar un proceso de borrado que llegue a todas las copias.' },
  { id: 'audit-log', term: 'Log de auditoría', en: 'Audit log', cat: 'seguridad', mods: ['m10'],
    deep: 'm10#audit-log', aliases: ['registro de auditoría', 'log de auditoría'],
    short: 'Registro solo-añadir de quién hizo qué, cuándo y desde dónde, guardado aparte y a prueba de manipulación (encadenado por hash, en almacenamiento inmutable). Distinto de los logs de aplicación: menos ruido, más retención y para investigar, no para depurar.' }
]);

/* ---------- M11: observabilidad y operación ---------- */
SD.defineGlossary([
  { id: 'observabilidad', term: 'Observabilidad', en: 'Observability', cat: 'metodo', mods: ['m11'],
    deep: 'm11#pilares', aliases: ['observability'],
    short: 'La capacidad de entender qué está pasando dentro de un sistema, incluso ante problemas que nadie anticipó, a partir de lo que emite: logs, métricas y traces.' },
  { id: 'trace', term: 'Trace distribuido', en: 'Distributed trace', cat: 'metodo', mods: ['m11'],
    deep: 'm11#traces', aliases: ['traces distribuidos', 'tracing distribuido', 'distributed tracing', 'trace'],
    short: 'El recorrido completo de una request por todos los servicios, formado por spans (una operación cada uno, con inicio, duración y atributos) unidos por un trace_id que viaja en cada llamada.' },
  { id: 'span', term: 'Span', en: 'Span', cat: 'metodo', mods: ['m11'],
    deep: 'm11#traces',
    short: 'Una operación dentro de un trace: una llamada HTTP, una consulta a la base, una generación del modelo. Tiene inicio, duración, atributos y un span padre.' },
  { id: 'cardinalidad', term: 'Cardinalidad', en: 'Metric cardinality', cat: 'metodo', mods: ['m11'],
    deep: 'm11#cardinalidad',
    short: 'Cantidad de combinaciones distintas de etiquetas de una métrica. Etiquetar con user_id o request_id genera millones de series y hace colapsar el sistema de métricas.' },
  { id: 'red-use', term: 'RED y USE', en: 'RED / USE methods', cat: 'metodo', mods: ['m11'],
    deep: 'm11#metricas', aliases: ['RED', 'USE', 'método RED', 'método USE'],
    short: 'Dos listas de qué medir. RED para servicios: tasa de requests, errores y duración. USE para recursos: utilización, saturación y errores.' },
  { id: 'burn-rate', term: 'Burn rate', en: 'Error budget burn rate', cat: 'metodo', mods: ['m11'],
    deep: 'm11#alertas',
    short: 'A qué velocidad se consume el error budget: 1× lo agota justo al final de la ventana; 14.4× agota un mes de presupuesto en unas 50 horas. Las buenas alertas se basan en esto.' },
  { id: 'canary', term: 'Canary', en: 'Canary release', cat: 'metodo', mods: ['m11', 'm19', 'm22'],
    deep: 'm11#despliegues', aliases: ['canaries', 'canary release'],
    short: 'Desplegar una versión nueva a una pequeña parte del tráfico, comparar sus métricas con la versión estable y avanzar o revertir automáticamente.' },
  { id: 'feature-flag', term: 'Feature flag', en: 'Feature flag', cat: 'metodo', mods: ['m11'],
    deep: 'm11#despliegues',
    short: 'Interruptor en tiempo de ejecución que activa o desactiva una funcionalidad sin desplegar. Separa desplegar código de liberar funcionalidad.' },
  { id: 'expand-contract', term: 'Expand / contract', en: 'Parallel change', cat: 'datos', mods: ['m11'],
    deep: 'm11#despliegues', aliases: ['expand/contract', 'expand-contract', 'expand and contract', 'parallel change'],
    short: 'Cambiar un esquema de base sin downtime en pasos compatibles: agregar lo nuevo, escribir en ambos, migrar los datos, leer de lo nuevo y recién al final quitar lo viejo.' },
  { id: 'postmortem', term: 'Postmortem sin culpas', en: 'Blameless postmortem', cat: 'metodo', mods: ['m11'],
    deep: 'm11#incidentes', aliases: ['postmortem', 'blameless postmortem'],
    short: 'Análisis escrito de un incidente que busca las causas del sistema (por qué fue posible el error) en lugar de culpables, y termina en acciones concretas con responsable.' },
  { id: 'opentelemetry', term: 'OpenTelemetry', en: 'OTel', cat: 'metodo', mods: ['m11'],
    deep: 'm11#traces', aliases: ['OTel', 'OTLP'],
    short: 'Estándar abierto (CNCF) para emitir traces, métricas y logs: una API y SDKs por lenguaje, un protocolo (OTLP), convenciones de nombres para los atributos y un Collector que recibe, procesa y exporta a cualquier backend.',
    related: ['trace', 'span'] },
  { id: 'tail-sampling', term: 'Muestreo por cola', en: 'Tail-based sampling', cat: 'metodo', mods: ['m11'],
    deep: 'm11#traces', aliases: ['tail sampling', 'tail-based sampling', 'head sampling', 'muestreo por cabeza'],
    short: 'Decidir qué traces guardar cuando ya terminaron, para quedarse con todos los que tienen errores o son lentos. El muestreo por cabeza (head sampling) decide al empezar, sin saber cómo terminará la request.',
    related: ['trace'] },
  { id: 'exemplar', term: 'Exemplar', en: 'Exemplar', cat: 'metodo', mods: ['m11'],
    deep: 'm11#exemplars', aliases: ['exemplars'],
    short: 'Un trace_id de ejemplo que se guarda junto a un punto de una métrica (por ejemplo, en el bucket de latencia más lento), para saltar del gráfico a una request concreta.',
    related: ['trace', 'observabilidad'] },
  { id: 'blue-green', term: 'Blue-green', en: 'Blue-green deployment', cat: 'metodo', mods: ['m11'],
    deep: 'm11#despliegues', aliases: ['blue/green', 'blue-green deployment'],
    short: 'Dos entornos completos: uno sirve el tráfico y el otro recibe la versión nueva. El cambio y el rollback son un cambio de ruta de segundos, a costa de duplicar la capacidad durante el despliegue.',
    related: ['canary'] },
  { id: 'runbook', term: 'Runbook', en: 'Runbook', cat: 'metodo', mods: ['m11'],
    deep: 'm11#alertas',
    short: 'Guía enlazada desde cada alerta: qué significa, cómo confirmar el impacto, qué mitigaciones probar primero y a quién escalar. Una alerta sin runbook obliga a improvisar a las 3 de la mañana.' }
]);

/* ---------- M12: un LLM visto por un ingeniero de sistemas ---------- */
SD.defineGlossary([
  { id: 'logits', term: 'Logits', en: 'Logits', cat: 'ia', mods: ['m12', 'm121'],
    deep: 'm12#caja',
    short: 'Los puntajes que devuelve el modelo para la posición siguiente, uno por cada token del vocabulario. Convertidos en probabilidades, son la base del muestreo.',
    related: ['sampling'] },
  { id: 'autorregresivo', term: 'Generación autorregresiva', en: 'Autoregressive generation', cat: 'ia', mods: ['m12'],
    deep: 'm12#caja', aliases: ['autorregresiva', 'autorregresivo', 'autoregressive'],
    short: 'Generar texto de a un token: cada token elegido se agrega a la entrada y el modelo vuelve a correr. Una respuesta de 500 tokens son 500 pasadas en serie.',
    related: ['decode', 'kv-cache'] },
  { id: 'sampling', term: 'Temperatura y top-p', en: 'Sampling', cat: 'ia', mods: ['m12', 'm121'],
    deep: 'm121#muestreo', aliases: ['top-p', 'top-k'],
    short: 'Cómo se elige el próximo token a partir de los logits. La temperatura aplana o afila la distribución, y top-p limita la elección a los tokens más probables que suman una probabilidad p. Con temperatura 0 se elige siempre el más probable.',
    related: ['logits'] },
  { id: 'tokenizer', term: 'Tokenizer', en: 'Tokenizer (BPE)', cat: 'ia', mods: ['m12'],
    deep: 'm12#tokens', aliases: ['BPE', 'byte pair encoding'],
    short: 'Convierte texto en IDs de tokens y de vuelta. Los actuales usan variantes de BPE con 100 000 a 200 000 piezas aprendidas de los datos; lo que no está en el vocabulario se parte en bytes.',
    related: ['token'] },
  { id: 'prefill', term: 'Prefill', en: 'Prefill', cat: 'ia', mods: ['m12', 'm121'],
    deep: 'm12#prefill-decode',
    short: 'La fase en que el modelo procesa todos los tokens del prompt a la vez, llena el KV cache y produce el primer token. Está limitada por el cómputo y decide buena parte del TTFT.',
    related: ['decode', 'ttft'] },
  { id: 'decode', term: 'Decode', en: 'Decode', cat: 'ia', mods: ['m12', 'm121'],
    deep: 'm12#prefill-decode',
    short: 'La fase que genera los tokens de salida de a uno: en cada paso se leen todos los pesos (y el KV cache) para producir un token por request. Está limitada por el ancho de banda de memoria.',
    related: ['prefill', 'itl'] },
  { id: 'gqa', term: 'GQA', en: 'Grouped-Query Attention', cat: 'ia', mods: ['m12', 'm121'],
    deep: 'm12#kv-cache', aliases: ['grouped-query attention', 'MQA', 'multi-query attention'],
    short: 'Varias cabezas de atención comparten un mismo par de K y V. Reduce el KV cache en proporción: Llama 3.1 70B, con 64 cabezas y 8 pares, guarda 8 veces menos que sin compartir. MQA es el extremo, con un solo par.',
    related: ['kv-cache', 'mla'] },
  { id: 'mla', term: 'MLA', en: 'Multi-head Latent Attention', cat: 'ia', mods: ['m12'],
    deep: 'm12#kv-cache', aliases: ['multi-head latent attention'],
    short: 'Variante de la atención de DeepSeek que guarda por token y capa un vector comprimido en lugar de K y V completos, y los reconstruye al usarlos. DeepSeek-V3 ocupa unos 70 kB de KV por token.',
    related: ['gqa', 'kv-cache'] },
  { id: 'goodput', term: 'Goodput', en: 'Goodput', cat: 'ia', mods: ['m12'],
    deep: 'm12#metricas',
    short: 'Requests por segundo que cumplen a la vez el SLO de TTFT y el de TPOT. Es lo que se optimiza en serving: el throughput se puede inflar llenando el batch hasta que nadie cumpla su SLO.',
    related: ['ttft', 'itl'] }
]);

/* ---------- M13: hardware GPU ---------- */
SD.defineGlossary([
  { id: 'tensor-core', term: 'Tensor core', en: 'Tensor core', cat: 'ia', mods: ['m13'],
    deep: 'm13#anatomia',
    short: 'Unidad de la GPU especializada en multiplicar matrices pequeñas en precisión reducida (BF16, FP8, FP4). Casi todo el cómputo de un LLM pasa por ellos.' },
  { id: 'flops', term: 'FLOPS', en: 'Floating-point operations per second', cat: 'ia', mods: ['m13'],
    deep: 'm13#cifras', aliases: ['FLOP', 'TFLOPS', 'PFLOPS'],
    short: 'Operaciones de punto flotante por segundo: la medida del cómputo de una GPU. Una H100 hace 989 billones por segundo (TFLOPS) en BF16. Las cifras de marketing suelen venir duplicadas "con sparsity".',
    related: ['mfu', 'roofline'] },
  { id: 'intensidad-aritmetica', term: 'Intensidad aritmética', en: 'Arithmetic intensity', cat: 'ia', mods: ['m13', 'm121'],
    deep: 'm13#roofline', aliases: ['arithmetic intensity'],
    short: 'Operaciones que hace una carga por cada byte que lee de memoria. Si es menor que el cociente entre FLOPS y ancho de banda de la GPU (unas 590 en una H100 con FP8), la carga está limitada por memoria.',
    related: ['roofline'] },
  { id: 'roofline', term: 'Modelo roofline', en: 'Roofline model', cat: 'ia', mods: ['m13', 'm121'],
    deep: 'm13#roofline', aliases: ['roofline'],
    short: 'Gráfico del rendimiento alcanzable según la intensidad aritmética: sube con el ancho de banda de memoria hasta el punto de quiebre y ahí se aplana en el pico de cómputo.',
    related: ['intensidad-aritmetica'] },
  { id: 'nvlink', term: 'NVLink', en: 'NVLink / NVSwitch', cat: 'ia', mods: ['m13'],
    deep: 'm13#multi-gpu', aliases: ['NVSwitch'],
    short: 'Interconexión de NVIDIA entre las GPUs de un servidor o de un rack, mucho más rápida que PCIe o la red: 900 GB/s por GPU en H100, sumando ambos sentidos. Es lo que hace viable el tensor parallelism.',
    related: ['infiniband', 'tensor-parallelism'] },
  { id: 'infiniband', term: 'InfiniBand', en: 'InfiniBand / RoCE', cat: 'ia', mods: ['m13'],
    deep: 'm13#multi-gpu', aliases: ['RoCE', 'RDMA'],
    short: 'Redes de baja latencia con RDMA que conectan servidores de GPUs. Una tarjeta de 400 Gb/s por GPU da 50 GB/s por sentido: alcanza para pipeline y para mover datos, no para sincronizar cada capa.',
    related: ['nvlink'] },
  { id: 'mfu', term: 'MFU', en: 'Model FLOPs Utilization', cat: 'ia', mods: ['m13', 'm121'],
    deep: 'm13#cifras', aliases: ['model FLOPs utilization'],
    short: 'Qué fracción del pico de FLOPS de las GPUs se usa en cómputo útil del modelo. Un buen entrenamiento logra entre 35 y 45 %; el decode, bastante menos.',
    related: ['flops'] }
]);

/* ---------- M14: cuantización ---------- */
SD.defineGlossary([
  { id: 'cuantizacion', term: 'Cuantización', en: 'Quantization', cat: 'ia', mods: ['m14'],
    deep: 'm14#como', aliases: ['cuantizar', 'cuantizado', 'cuantizada', 'cuantizados', 'cuantizadas', 'quantization'],
    short: 'Guardar pesos, activaciones o el KV cache en menos bits (FP8, INT4, FP4), con escalas que llevan cada grupo de valores a su rango. Reduce memoria y acelera el decode a cambio de algo de calidad, que hay que medir.',
    related: ['fp8', 'formatos-4bit', 'calibracion'] },
  { id: 'bf16', term: 'BF16 y FP16', en: 'bfloat16 / half precision', cat: 'ia', mods: ['m14'],
    deep: 'm14#formatos', aliases: ['BF16', 'FP16', 'bfloat16'],
    short: 'Formatos de 16 bits. BF16 conserva el rango de FP32 (8 bits de exponente) con menos precisión, y es el formato nativo de casi todos los LLM actuales. FP16 tiene más precisión pero un máximo de 65 504, y se desborda con facilidad.',
    related: ['fp8'] },
  { id: 'fp8', term: 'FP8', en: 'FP8 (E4M3 / E5M2)', cat: 'ia', mods: ['m14'],
    deep: 'm14#formatos', aliases: ['E4M3', 'E5M2'],
    short: 'Punto flotante de 8 bits. E4M3, hasta 448, se usa para pesos y activaciones; E5M2, hasta 57 344, para gradientes. Desde la H100, las GPUs calculan en FP8 al doble de velocidad que en BF16.',
    related: ['bf16', 'cuantizacion'] },
  { id: 'formatos-4bit', term: 'INT8, INT4 y FP4', en: 'Low-bit formats', cat: 'ia', mods: ['m14'],
    deep: 'm14#formatos', aliases: ['INT8', 'INT4', 'FP4', 'NVFP4', 'MXFP4'],
    short: 'Formatos de 8 y 4 bits que solo funcionan con escalas por grupo o por bloque. INT4 guarda enteros de −8 a 7; FP4 (E2M1) solo representa 0, 0.5, 1, 1.5, 2, 3, 4 y 6, y Blackwell lo calcula de forma nativa con escalas cada 16 o 32 valores.',
    related: ['cuantizacion'] },
  { id: 'wxay', term: 'W4A16 y W8A8', en: 'Weight / activation precision', cat: 'ia', mods: ['m14'],
    deep: 'm14#que', aliases: ['W4A16', 'W8A16', 'W8A8', 'weight-only'],
    short: 'Notación de qué se cuantiza: W4A16 guarda los pesos en 4 bits y calcula en 16, lo que acelera el decode porque se leen menos bytes. W8A8 cuantiza también las activaciones y usa tensor cores de 8 bits, lo que acelera además el prefill.',
    related: ['cuantizacion'] },
  { id: 'gptq', term: 'GPTQ', en: 'GPTQ', cat: 'ia', mods: ['m14'],
    deep: 'm14#metodos',
    short: 'Método de cuantización de pesos a 3 o 4 bits (2022) que cuantiza los pesos de una capa de a uno y ajusta los restantes para compensar el error, con información de segundo orden sacada de datos de calibración.',
    related: ['awq', 'calibracion'] },
  { id: 'awq', term: 'AWQ', en: 'Activation-aware Weight Quantization', cat: 'ia', mods: ['m14'],
    deep: 'm14#metodos',
    short: 'Método de cuantización de pesos a 4 bits (2023) que protege el ~1 % de canales más importantes, reconocidos por el tamaño de sus activaciones, agrandándolos antes de cuantizar.',
    related: ['gptq', 'smoothquant'] },
  { id: 'smoothquant', term: 'SmoothQuant', en: 'SmoothQuant', cat: 'ia', mods: ['m14'],
    deep: 'm14#metodos',
    short: 'Técnica para cuantizar pesos y activaciones a 8 bits (2022): divide los canales de activación con outliers por un factor y multiplica los pesos por el mismo factor, así ambas partes quedan fáciles de cuantizar sin cambiar el resultado.',
    related: ['awq'] },
  { id: 'calibracion', term: 'Datos de calibración', en: 'Calibration data', cat: 'ia', mods: ['m14'],
    deep: 'm14#metodos', aliases: ['calibración', 'calibrar'],
    short: 'Unos cientos de ejemplos de texto que los métodos de cuantización usan para decidir escalas y redondeos. Tienen que parecerse al tráfico real: si no, la calidad cae justo donde no se midió.',
    related: ['cuantizacion'] }
]);

/* ---------- M15: motores de inferencia ---------- */
SD.defineGlossary([
  { id: 'continuous-batching', term: 'Continuous batching', en: 'Iteration-level scheduling', cat: 'ia', mods: ['m15'],
    deep: 'm15#batching', aliases: ['continuous batching', 'static batching'],
    short: 'Rearmar el batch en cada paso de decode: la request que termina sale y una que esperaba entra en ese mismo paso. Con respuestas de largos variables, multiplica el throughput respecto del static batching, que espera a la respuesta más larga.',
    related: ['pagedattention'] },
  { id: 'pagedattention', term: 'PagedAttention', en: 'PagedAttention', cat: 'ia', mods: ['m15'],
    deep: 'm15#paged', aliases: ['tabla de bloques', 'block table'],
    short: 'Administrar el KV cache en bloques de pocos tokens, con una tabla por request que traduce bloques lógicos a físicos, como la memoria virtual. Limita el desperdicio al último bloque y permite compartir bloques entre requests.',
    related: ['kv-cache', 'continuous-batching', 'prefix-caching'] },
  { id: 'prefix-caching', term: 'Prefix caching', en: 'Prefix caching', cat: 'ia', mods: ['m15', 'm19'],
    deep: 'm15#prefix', aliases: ['RadixAttention', 'automatic prefix caching'],
    short: 'Reutilizar el KV cache de prefijos que se repiten (prompt de sistema, ejemplos, la conversación anterior) para saltear su prefill. Baja el TTFT y el cómputo, y solo sirve si la request llega a la réplica que tiene ese cache.',
    related: ['pagedattention', 'prompt-caching'] },
  { id: 'chunked-prefill', term: 'Chunked prefill', en: 'Chunked prefill', cat: 'ia', mods: ['m15'],
    deep: 'm15#chunked',
    short: 'Partir el prefill de un prompt largo en trozos y mezclarlos con los pasos de decode de las demás requests, dentro de un presupuesto de tokens por iteración, para que un prompt largo no congele el TPOT de todos.',
    related: ['prefill', 'desagregacion'] },
  { id: 'desagregacion', term: 'Prefill y decode desagregados', en: 'Disaggregated serving', cat: 'ia', mods: ['m15'],
    deep: 'm15#desagregado', aliases: ['desagregación', 'disaggregated serving', 'disaggregated prefill'],
    short: 'Hacer el prefill en un grupo de GPUs y el decode en otro, moviendo el KV cache de cada request por una red rápida. Evita que las fases compitan y permite dimensionar cada grupo para su SLO, a cambio de transferir gigabytes por request.',
    related: ['chunked-prefill'] },
  { id: 'speculative-decoding', term: 'Speculative decoding', en: 'Speculative decoding', cat: 'ia', mods: ['m15'],
    deep: 'm15#speculative', aliases: ['decodificación especulativa', 'draft model', 'Medusa', 'EAGLE'],
    short: 'Un modelo chico propone varios tokens y el grande los verifica en una sola pasada, aceptando los que coinciden. El resultado tiene la misma distribución que el modelo grande solo; acelera el decode cuando sobra cómputo, con pocos usuarios.',
    related: ['decode'] },
  { id: 'pipeline-parallelism', term: 'Pipeline parallelism', en: 'Pipeline parallelism', cat: 'ia', mods: ['m15'],
    deep: 'm15#paralelismo', aliases: ['PP'],
    short: 'Repartir el modelo en tramos de capas, cada uno en otra GPU o servidor, que se pasan las activaciones. Se comunica poco, así que sirve entre servidores, pero suma latencia y deja burbujas si no hay suficientes requests.',
    related: ['tensor-parallelism', 'expert-parallelism'] },
  { id: 'expert-parallelism', term: 'Expert parallelism', en: 'Expert parallelism', cat: 'ia', mods: ['m15'],
    deep: 'm15#paralelismo', aliases: ['EP'],
    short: 'En un modelo MoE, poner distintos expertos en distintas GPUs; cada token viaja a las GPUs de sus expertos y vuelve (all-to-all). Permite servir MoE enormes repartiendo sus expertos entre muchas GPUs.',
    related: ['moe', 'pipeline-parallelism'] },
  { id: 'moe', term: 'MoE', en: 'Mixture of Experts', cat: 'ia', mods: ['m12', 'm15'],
    deep: 'm15#paralelismo', aliases: ['mixture of experts'],
    short: 'Arquitectura en la que cada capa tiene muchos expertos y cada token usa solo unos pocos: DeepSeek-V3 tiene 671 mil millones de parámetros y usa 37 por token. Calcula como un modelo chico, pero ocupa la memoria de uno grande.',
    related: ['expert-parallelism'] },
  { id: 'flashattention', term: 'FlashAttention', en: 'FlashAttention', cat: 'ia', mods: ['m15', 'm121'],
    deep: 'm121#flash',
    short: 'Kernel que calcula la atención por bloques que caben en la SRAM del chip, sin escribir la matriz de atención completa en la HBM. Da el mismo resultado exacto con mucho menos tráfico de memoria.',
    related: ['hbm'] }
]);

/* ---------- M16: context windows ---------- */
SD.defineGlossary([
  { id: 'context-window', term: 'Ventana de contexto', en: 'Context window', cat: 'ia', mods: ['m16'],
    deep: 'm16#limites', aliases: ['context window', 'ventanas de contexto'],
    short: 'La cantidad máxima de tokens que el modelo procesa en una request, entrada más respuesta. La limitan el entrenamiento, la memoria del KV cache y el costo cuadrático de la atención; que un token entre no garantiza que el modelo lo use bien.',
    related: ['kv-cache', 'rope', 'rag'] },
  { id: 'lost-in-the-middle', term: 'Lost in the middle', en: 'Lost in the middle', cat: 'ia', mods: ['m16'],
    deep: 'm16#limites',
    short: 'Los modelos encuentran mejor la información al principio y al final del contexto que en el medio (estudio de 2023). Por eso lo importante se pone en los extremos del prompt, y llenar la ventana "por las dudas" empeora las respuestas.',
    related: ['context-window'] },
  { id: 'rag', term: 'RAG', en: 'Retrieval-Augmented Generation', cat: 'ia', mods: ['m16', 'm20'],
    deep: 'm16#rag', aliases: ['retrieval-augmented generation'],
    short: 'Buscar en un índice los fragmentos relevantes para la pregunta y agregarlos al prompt. Escala a corpus de cualquier tamaño a bajo costo por pregunta; su punto débil es que la búsqueda no traiga lo que hacía falta.',
    related: ['context-window'] },
  { id: 'rope', term: 'RoPE', en: 'Rotary Position Embedding', cat: 'ia', mods: ['m16'],
    deep: 'm16#rope', aliases: ['YaRN', 'rotary position embedding'],
    short: 'Codificación posicional que rota los vectores de consulta y clave según la posición del token. Para extender la ventana de un modelo se estiran esas rotaciones (Position Interpolation, NTK, YaRN) y se entrena un poco con textos largos.',
    related: ['context-window'] },
  { id: 'sliding-window-attention', term: 'Atención de ventana deslizante', en: 'Sliding window attention', cat: 'ia', mods: ['m16'],
    deep: 'm16#rope', aliases: ['sliding window attention'],
    short: 'Cada token atiende solo a los últimos miles de tokens en lugar de a todos. Acota el KV cache y el cómputo de esas capas; varios modelos la alternan con capas globales que ven todo el contexto.',
    related: ['rope'] },
  { id: 'prompt-caching', term: 'Prompt caching', en: 'Prompt caching', cat: 'ia', mods: ['m16', 'm25'],
    deep: 'm16#prompt-caching', aliases: ['context caching'],
    short: 'Reutilizar el KV cache de un prefijo de prompt idéntico a uno reciente y cobrar esos tokens con descuento. Exige poner lo estable (sistema, herramientas, documentos) al principio y lo que cambia al final.',
    related: ['prefix-caching'] }
]);

/* ---------- M17: diseño de la API del LLM ---------- */
